insert into public.industries (id, name, slug, description, intro, semantic_weight, enabled, display_order) values
  ('fintech', 'Fintech & Payments', 'fintech', 'Payments, wallets, billing, invoicing, merchant services, lending and personal finance tools.', 'Fintech & Payments names work best when the vocabulary of the domain is recognisable at a glance. The engine draws on wallet, ledger, billing, invoice, checkout, merchant and similar terms for this industry.', 1, true, 10),
